// ResearchProgress — the research wait is 60-90s; a static spinner reads as
// frozen. This shows the SAME animated Prism tuning fork (ambient life) plus a
// narration of the phases the research actually moves through, advancing on a
// timed cadence: done steps check off, the current step is lit. The point isn't
// a real progress bar (we can't see inside the model) — it's making a long wait
// legible, so it reads as diligence, not a hang.
function ResearchProgress({ contactName, phase = 'researching' }) {
  const name = (contactName && contactName !== 'the recipient') ? contactName : 'them';
  const STEPS = phase === 'identifying'
    ? [
        { t: 'Matching your identifiers', s: 'Email, phone, and name against public records' },
        { t: 'Finding candidate profiles', s: 'LinkedIn, firm sites, directories' },
        { t: 'Confirming it’s the right person', s: 'Cross-checking the details line up' },
      ]
    : [
        { t: 'Searching public sources', s: 'LinkedIn, company sites, news, licenses' },
        { t: 'Reading the evidence', s: 'Bio, posts, press, professional history' },
        { t: 'Cross-referencing', s: 'Confirming facts across multiple sources' },
        { t: 'Reading behavioral signals', s: 'How they present, decide, and communicate' },
        { t: 'Building the DISC read', s: 'Turning evidence into a behavioral profile' },
        { t: 'Writing your connection plan', s: 'How to open, what to lean into' },
      ];
  // Advance through steps on a cadence that roughly fills the expected window,
  // holding on the LAST step (so it never looks "done" before the data lands).
  const [i, setI] = useState(0);
  const per = phase === 'identifying' ? 4000 : 12000;
  useEffect(() => {
    const id = setInterval(() => setI((x) => Math.min(x + 1, STEPS.length - 1)), per);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div style={{ padding: '18px 16px 8px', textAlign: 'center' }}>
      <div className="fork-stage" style={{ width: 118, height: 118, marginBottom: 14 }}>
        <span className="fork-glow" />
        <span className="fork-ring fr1" />
        <span className="fork-ring fr2" />
        <span className="fork-ring fr3" />
        <svg className="fork-ico" viewBox="0 0 40 40" fill="none" aria-hidden="true">
          <g stroke="#EBCB82" strokeWidth="1.1" strokeLinecap="round" fill="none" opacity="0.55"><path d="M30 11 Q34 17 30 23"/><path d="M10 11 Q6 17 10 23"/></g>
          <g stroke="#CBA35C" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none"><path d="M15 6 V21"/><path d="M25 6 V21"/><path d="M15 21 C15 26 17 28 20 28 C23 28 25 26 25 21"/><path d="M20 28 V36"/></g>
          <circle cx="20" cy="37.4" r="2" fill="#EBCB82"/>
        </svg>
      </div>
      <div className="fork-eyebrow">✦ {phase === 'identifying' ? 'Ari is looking' : 'Ari is researching'}</div>
      <div className="fork-title" style={{ fontSize: 22, marginBottom: 4 }}>{phase === 'identifying' ? `Finding ${name}` : `Reading up on ${name}`}</div>
      <div style={{ fontSize: 11, color: 'var(--text-3)', marginBottom: 16 }}>{phase === 'identifying' ? 'A few seconds…' : 'About a minute — worth the wait.'}</div>

      <div style={{ textAlign: 'left', maxWidth: 320, margin: '0 auto', display: 'flex', flexDirection: 'column', gap: 9 }}>
        {STEPS.map((step, idx) => {
          const done = idx < i;
          const active = idx === i;
          return (
            <div key={idx} style={{ display: 'flex', alignItems: 'flex-start', gap: 11, opacity: done || active ? 1 : 0.4, transition: 'opacity .4s' }}>
              <span style={{ flex: 'none', width: 18, height: 18, marginTop: 1, borderRadius: 9, display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                background: done ? 'var(--accent-2, #EBCB82)' : 'transparent',
                border: done ? 'none' : `1.5px solid ${active ? 'var(--accent-2, #EBCB82)' : 'var(--border)'}`,
                color: '#1a1409', fontSize: 11, fontWeight: 800 }}>
                {done ? '✓' : active ? <span className="rp-pulse-dot" /> : ''}
              </span>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: active ? 700 : 600, color: active ? 'var(--text-1)' : done ? 'var(--text-2)' : 'var(--text-3)' }}>{step.t}</div>
                {active && <div style={{ fontSize: 11, color: 'var(--text-3)', marginTop: 1, lineHeight: 1.4 }}>{step.s}</div>}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ForkTuningOverlay({ contactName, discLabel }) {
  const name = (contactName && contactName !== 'the recipient') ? contactName : null;
  const d = (discLabel || '').trim();
  return createPortal(
    <div className="fork-ov" role="status" aria-live="polite">
      <div className="fork-ov-inner">
        <div className="fork-stage">
          <span className="fork-glow" />
          <span className="fork-ring fr1" />
          <span className="fork-ring fr2" />
          <span className="fork-ring fr3" />
          <svg className="fork-ico" viewBox="0 0 40 40" fill="none" aria-hidden="true">
            <g stroke="#EBCB82" strokeWidth="1.1" strokeLinecap="round" fill="none" opacity="0.55"><path d="M30 11 Q34 17 30 23"/><path d="M10 11 Q6 17 10 23"/></g>
            <g stroke="#CBA35C" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none"><path d="M15 6 V21"/><path d="M25 6 V21"/><path d="M15 21 C15 26 17 28 20 28 C23 28 25 26 25 21"/><path d="M20 28 V36"/></g>
            <circle cx="20" cy="37.4" r="2" fill="#EBCB82"/>
          </svg>
        </div>
        <div className="fork-eyebrow">✦ Ari is tuning</div>
        <div className="fork-title">{name ? `Tuning to ${name}` : 'Tuning your message'}</div>
        <div className="fork-sub">{d ? `Matching your voice to their ${d} style` : `Matching your voice to how ${name || 'they'} read best`}</div>
      </div>
    </div>,
    document.body
  );
}


// ── splitQuotedReply ─────────────────────────────────────────────────────────
// A reply body is two different things stuck together: what YOU just wrote, and
// the thread you are replying to. Rewriting the whole box rewrites the other
// person's words too — which is both wrong and, on a long thread, expensive.
//
// Returns { body, quoted } where body is the part actually being composed. The
// boundary is whichever attribution line comes FIRST, because mail clients each
// use their own and a forwarded chain can contain several.
//
// Deliberately conservative: if no boundary is recognised the whole text is
// treated as the body. Failing to split is a minor annoyance; splitting in the
// wrong place would silently drop what someone wrote.
export function splitQuotedReply(text) {
  const src = String(text || '');
  if (!src.trim()) return { body: src, quoted: '' };
  const lines = src.split('\n');
  const MARKERS = [
    /^\s*On .{4,120}\bwrote:\s*$/i,          // Gmail / Apple: "On <date>, <name> wrote:"
    /^\s*-{2,}\s*Original Message\s*-{2,}/i, // Outlook
    /^\s*-{2,}\s*Forwarded message\s*-{2,}/i,
    /^\s*_{5,}\s*$/,                          // Outlook's underscore rule
    /^\s*From:\s*.+/i,                        // Outlook header block
    /^\s*Sent from my \w+/i,                  // signature that precedes a quote
  ];
  let cut = -1;
  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i];
    if (MARKERS.some(re => re.test(ln))) { cut = i; break; }
    // A run of quoted lines counts too, but one stray ">" does not — a single
    // line could easily be an arrow or a fragment the user typed themselves.
    if (/^\s*>/.test(ln) && /^\s*>/.test(lines[i + 1] || '')) { cut = i; break; }
  }
  if (cut < 0) return { body: src, quoted: '' };
  return { body: lines.slice(0, cut).join('\n'), quoted: lines.slice(cut).join('\n') };
}

function AriRewriteButton({ text, onRewrite, contactName, discLabel, sourceText, contactId, textareaRef }) {
  const [busy, setBusy] = useState(false);
  const [prev, setPrev] = useState(null);
  const [err, setErr] = useState(null);
  const [scope, setScope] = useState(null); // remembers a selection-only rewrite for undo
  const [note, setNote] = useState(null);   // says what was actually rewritten
  const go = async () => {
    if (!text || !text.trim()) { setErr('Write a draft first.'); return; }
    // If the user has highlighted part of the draft, rewrite ONLY that — leave
    // the rest (e.g. a forwarded message below) untouched. Otherwise rewrite all.
    const ta = textareaRef && textareaRef.current;
    let selStart = -1, selEnd = -1, selected = '';
    if (ta && typeof ta.selectionStart === 'number' && ta.selectionEnd > ta.selectionStart) {
      selStart = ta.selectionStart; selEnd = ta.selectionEnd;
      selected = text.slice(selStart, selEnd);
    }
    // Precedence: an explicit highlight wins (most specific intent), otherwise
    // rewrite only the newly-composed part and leave the quoted thread alone.
    const usingSelection = selected.trim().length > 0;
    const split = usingSelection ? null : splitQuotedReply(text);
    if (!usingSelection && split && split.quoted && !split.body.trim()) {
      setErr('Write your reply above the quoted thread first.');
      return;
    }
    const autoScoped = !usingSelection && !!(split && split.quoted && split.body.trim());
    const toRewrite = usingSelection ? selected : (autoScoped ? split.body : text);
    setErr(null); setNote(null); setBusy(true);
    const { data, error } = await supabase.functions.invoke('ari-rewrite', { body:{ draft: toRewrite, contact_name:contactName||'the recipient', contact_id:contactId, disc_label:discLabel||'', source_text:sourceText||'' } });
    setBusy(false);
    if (error || data?.error || !data?.message) { setErr('Rewrite failed — try again.'); return; }
    setPrev(text);
    if (usingSelection) {
      // splice the rewritten selection back into the full draft, preserving
      // leading/trailing whitespace so surrounding text stays intact
      const rewritten = String(data.message);
      const next = text.slice(0, selStart) + rewritten + text.slice(selEnd);
      setScope({ start: selStart, len: rewritten.length });
      onRewrite(next);
      // restore a caret/selection around the rewritten span after render
      setTimeout(() => {
        if (ta) { try { ta.focus(); ta.setSelectionRange(selStart, selStart + rewritten.length); } catch (_) {} }
      }, 0);
    } else if (autoScoped) {
      // Reattach the thread exactly as it was — not re-generated, not reflowed.
      const rewritten = String(data.message).replace(/\s+$/, '');
      setScope(null);
      onRewrite(rewritten + '\n' + split.quoted);
      setNote('Rewrote your message — the quoted thread below was left untouched.');
    } else {
      setScope(null);
      onRewrite(data.message);
    }
  };
  const undo = () => { if (prev==null) return; onRewrite(prev); setPrev(null); setScope(null); };
  return (
    <div style={{display:'flex',justifyContent:'flex-end',alignItems:'center',gap:'6px',marginBottom:'6px'}}>
      {busy && <ForkTuningOverlay contactName={contactName} discLabel={discLabel} />}
      {err && <span style={{fontSize:'10px',color:'var(--red)',marginRight:'auto'}}>{err}</span>}
      {!err && note && <span style={{fontSize:'10px',color:'var(--text-3)',marginRight:'auto'}}>{note}</span>}
      {prev!=null && <button type="button" className="btn btn-ghost btn-sm" style={{padding:'2px 8px',fontSize:'11px'}} onClick={undo}>Undo</button>}
      <button type="button" className="btn btn-ghost btn-sm" disabled={busy} onClick={go} title="Rewrite in your voice. Highlight part of the draft to rewrite only that." style={{padding:'2px 9px',fontSize:'11px',color:'var(--accent)',border:'1px solid var(--accent-dim)'}}>{busy?'✨ Ari is writing…':'✨ Ari rewrite'}</button>
    </div>
  );
}

// ─────────────────────────────────────────
// MAIN APP
// ─────────────────────────────────────────
// ─────────────────────────────────────────
// PWA INSTALL PROMPT
// ─────────────────────────────────────────
// When the site is opened in a regular mobile browser tab, the URL bar,
// address bar, and tab counter eat ~110px of vertical space and constantly
// remind the user this is "just a website." Installing the PWA solves that
// — when launched from the home screen it runs without browser chrome.
//
// This component:
//   1. Hides itself entirely once running standalone (already installed)
//   2. On Android Chrome / Edge: captures beforeinstallprompt and offers a
//      one-tap Install button that fires the real browser install dialog
//   3. On iOS Safari: the event doesn't fire (Apple doesn't expose it), so
//      it shows static instructions: "Tap Share, then Add to Home Screen"
//   4. Remembers a dismissal for 7 days via localStorage so it doesn't nag
function InstallPwaPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState(null);
  const [visible, setVisible] = useState(false);
  const [showIosHelp, setShowIosHelp] = useState(false);

  useEffect(() => {
    // If already running as installed PWA, never show
    const inStandalone = window.matchMedia('(display-mode: standalone)').matches
      || window.navigator.standalone === true; // iOS-specific flag
    if (inStandalone) return;

    // Respect dismissal window (7 days)
    try {
      const dismissed = Number(localStorage.getItem('pwa_install_dismissed_at') || 0);
      if (dismissed && Date.now() - dismissed < 7 * 24 * 60 * 60 * 1000) return;
    } catch (_) {}

    // Detect iOS Safari — beforeinstallprompt never fires there
    const ua = window.navigator.userAgent || '';
    const isIos = /iPad|iPhone|iPod/.test(ua) && !window.MSStream;
    const isSafari = /Safari/.test(ua) && !/CriOS|FxiOS|EdgiOS/.test(ua);
    if (isIos && isSafari) {
      setShowIosHelp(true);
      setVisible(true);
      return;
    }

    // Android Chrome path
    function onBeforeInstall(e) {
      e.preventDefault();          // stop the mini-infobar; we'll show our own UI
      setDeferredPrompt(e);
      setVisible(true);
    }
    function onInstalled() {
      setVisible(false);
      setDeferredPrompt(null);
    }
    window.addEventListener('beforeinstallprompt', onBeforeInstall);
    window.addEventListener('appinstalled', onInstalled);
    return () => {
      window.removeEventListener('beforeinstallprompt', onBeforeInstall);
      window.removeEventListener('appinstalled', onInstalled);
    };
  }, []);

  async function handleInstall() {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    try { await deferredPrompt.userChoice; } catch (_) {}
    setDeferredPrompt(null);
    setVisible(false);
  }
  function dismiss() {
    try { localStorage.setItem('pwa_install_dismissed_at', String(Date.now())); } catch (_) {}
    setVisible(false);
  }
  if (!visible) return null;

  return (
    <div className="pwa-install-banner">
      <div className="pwa-install-icon">⤓</div>
      <div className="pwa-install-text">
        {showIosHelp ? (
          <>
            <strong>Install PrismOS</strong>
            <span>Tap <span style={{whiteSpace:'nowrap'}}>Share ↑</span>, then <span style={{whiteSpace:'nowrap'}}>"Add to Home Screen"</span></span>
          </>
        ) : (
          <>
            <strong>Install PrismOS</strong>
            <span>Hide the browser bar — install as an app</span>
          </>
        )}
      </div>
      {!showIosHelp && (
        <button type="button" className="pwa-install-btn" onClick={handleInstall}>Install</button>
      )}
      <button type="button" className="pwa-install-dismiss" onClick={dismiss} aria-label="Dismiss">×</button>
    </div>
  );
}

